   "lead": "L'Ucraina ha lanciato più di 1.000 droni contro il territorio russo, in uno dei più grandi attacchi aerei dell'intera guerra, colpendo e incendiando diversi impianti petroliferi. L'operazione arriva in un momento di tensioni crescenti tra Kiev e Washington. Lo riferisce Al Jazeera.",
