   "sez": "dibattito",
   "titolo": "In Albania proseguono le proteste studentesche, scontri con la polizia a Tirana",
   "orig": "Anti-government protesters battle with police in Albania",
   "lead": "Per il quinto giorno consecutivo migliaia di studenti albanesi protestano a Tirana contro il costo dell'istruzione e la corruzione, in manifestazioni che sabato sono sfociate in violenti scontri con la polizia antisommossa. I manifestanti hanno incendiato un edificio governativo, due banche e la sede della Corte Suprema; decine di persone sono state fermate. Le fonti non riportano risposte specifiche delle autorità alle richieste degli studenti. Lo riferiscono BBC, Al Jazeera e The Guardian.",
   "more": [
    "Le proteste studentesche in Albania si inseriscono in un clima di tensione sociale legato ai costi crescenti dell'istruzione e a diffuse accuse di corruzione nelle istituzioni pubbliche, temi che da anni alimentano manifestazioni nel paese, candidato all'adesione all'Unione europea."
   ],
