   "titolo": "Schlein: \"Pronta a candidarmi premier, con o senza le primarie\"",
   "orig": "Schlein: \"Pronta a candidarmi premier, con o senza primarie\"",
   "lead": "Dal palco dell'Assemblea Nazionale del Pd, la segretaria Elly Schlein ha rilanciato la propria candidatura a premier per il centrosinistra, dicendosi pronta a correre \"con o senza primarie\" e puntando su un'alleanza progressista unita per le prossime elezioni politiche. L'assemblea ha prorogato il suo mandato di segretaria, mentre sarà l'unica candidata del Pd alla competizione; la componente riformista del partito si è astenuta, definendo la scelta \"una forzatura\". Lo riferiscono San Marino RTV, ANSA e la Repubblica.",
   "more": [
    "Le primarie sono il meccanismo con cui il Pd e le coalizioni di centrosinistra scelgono tradizionalmente il proprio candidato alla premiership, aprendo il voto anche a elettori esterni al partito; rinunciarvi significa una scelta presa direttamente dai vertici del partito."
   ],
