   "id": "z96c4b32c",
   "sez": "sport",
   "titolo": "Davidovich Fokina conquista lo Shanghai Masters battendo Jodar",
   "orig": "After years of frustration, Davidovich Fokina wins third title of 2026",
   "lead": "Lo spagnolo Alejandro Davidovich Fokina ha vinto domenica lo Shanghai Masters, battendo in finale il connazionale Rafael Jodar con il punteggio di 1-6, 7-6, 6-4. È il terzo titolo del 2026 per il tennista, che pone fine al sorprendente percorso di Jodar nel torneo. Nella stessa giornata, a Wuhan, la polacca Maja Chwalinska ha conquistato il suo primo titolo in carriera superando in finale la britannica Sonay Kartal, finalista al Roland Garros, con il risultato di 2-6, 6-4, 6-4; Kartal diventerà comunque la nuova numero 1 britannica grazie a questo risultato.",
   "more": [
    "Il Masters 1000 di Shanghai è uno dei torneo più prestigiosi del circuito ATP, disputato su cemento in Cina. I torneo WTA come quello di Wuhan assegnano punti importanti per il ranking mondiale femminile, e vincere il primo titolo in carriera rappresenta spesso una svolta significativa per una tennista."
   ],
