   "titolo": "FMI e Banca Mondiale, incontri senza risposte per i paesi in via di sviluppo",
   "orig": "IMF/World Bank meetings leave developing countries with more questions than answers",
   "lead": "Gli incontri della settimana scorsa tra Fondo Monetario Internazionale e Banca Mondiale non hanno fornito nuove risposte ai paesi in via di sviluppo riguardo alle sfide poste dall'espansione del conflitto in Medio Oriente, dalla guerra in Ucraina, dall'aumento del peso del debito e dal rischio di una bolla legata all'intelligenza artificiale. Secondo quanto riportato, le questioni restano aperte dopo i vertici. Lo riferisce Bangkok Post.",
   "more": [
    "Gli incontri annuali di FMI e Banca Mondiale riuniscono ministri delle finanze e banchieri centrali di tutto il mondo per discutere stabilità finanziaria globale, debito sovrano e sviluppo economico. I paesi in via di sviluppo chiedono da anni maggiore accesso ai capitali e riduzione del peso debitorio, in un contesto di crescenti tensioni geopolitiche."
   ],
