   "titolo": "I Rays a un passo dalla World Series dopo la vittoria sui Guardians",
   "orig": "Los Rays quedaron a un triunfo de regresar a la Serie Mundial tras vencer a los Guardianes",
   "lead": "I Tampa Bay Rays hanno battuto 3-1 i Cleveland Guardians in gara 5 della serie di campionato della American League, portandosi avanti 3-2 nella serie al meglio delle sette gare. La squadra, che non ha mai vinto una World Series, è ora a una sola vittoria dal qualificarsi per la sua terza finale, dopo le sconfitte del 2008 e del 2020. Decisivo il lancio di Drew Rasmussen, che ha tenuto a lungo a bada l'attacco di Cleveland.",
   "more": [
    "La American League Championship Series è la semifinale della Major League Baseball che determina la squadra che rappresenterà la American League nella World Series, la finale del campionato. I Rays, franchigia con sede in Florida, hanno disputato due World Series senza mai vincerle."
   ],
