   "id": "ze29366c5",
   "sez": "salute",
   "titolo": "Uno studio collega il contatto con la natura a abitudini alimentari più sane",
   "orig": "Contact With Nature is Linked to Healthy Eating, Shows Encouraging New Study",
   "lead": "Una nuova ricerca dell'Anglia Ruskin University nel Regno Unito ha scoperto che il contatto con la natura può favorire lo sviluppo di abitudini alimentari più sane. Lo studio, pubblicato sulla rivista Body Image e condotto su 500 adulti britannici, sarebbe il primo a fornire prove che l'esposizione agli ambienti naturali può influenzare il rapporto delle persone con il cibo. Lo riferisce Good News Network.",
   "more": [
    "Il legame tra benessere psicologico e ambiente naturale è oggetto di crescente interesse scientifico: diversi studi hanno già mostrato che il contatto con spazi verdi riduce stress e ansia, fattori che a loro volta influenzano comportamenti alimentari e immagine corporea."
   ],
