   "id": "zdfeccbe4",
   "sez": "mondo",
   "titolo": "RD Congo, polemica sui fondi destinati alla sensibilizzazione contro l'Ebola",
   "orig": "Fonds Ebola : une polémique autour des enveloppes allouées aux caucus des députés de l’Ituri, du Nord-Kivu et du Haut-Uélé",
   "lead": "Nella Repubblica Democratica del Congo è scoppiata una polemica riguardo ai fondi destinati a sostenere la sensibilizzazione delle popolazioni contro il virus Ebola, con deputati nazionali dell'Ituri, del Nord-Kivu e dell'Alto Uele coinvolti in accuse reciproche. Al centro della controversia ci sono accuse di cattiva gestione delle risorse, richieste di spiegazioni e appelli alla trasparenza. Diverse questioni restano senza risposta sull'utilizzo effettivo dei fondi. Lo riferisce Radio Okapi.",
   "more": [
    "L'Ebola è una malattia virale emorragica grave, ricorrente in alcune regioni della Repubblica Democratica del Congo. Le campagne di sensibilizzazione delle popolazioni sono considerate uno strumento essenziale per contenere i contagi, e la gestione dei fondi pubblici destinati a queste iniziative è spesso oggetto di controllo politico e mediatico."
   ],
