   "id": "z7e89d7fc",
   "sez": "salute",
   "titolo": "A Hong Kong la realtà mista aiuta i bambini malati di cancro ad affrontare la radioterapia",
   "orig": "The human touch behind the virtual technology for preparing child cancer patients",
   "lead": "Una docente dell'Università Politecnica di Hong Kong, Shara Lee Wee-yee, utilizza un programma di realtà mista chiamato HEROCARE per ridurre la paura e l'incertezza nei bambini malati di cancro prima della radioterapia. Il sistema permette simulazioni personalizzate che consentono alle famiglie di vivere in anticipo l'esperienza del trattamento prima di entrare in ospedale. Secondo quanto riferito dalla South China Morning Post, lo strumento aiuta anche i caregiver a capire cosa aspettarsi e serve a formare i futuri radioterapisti nelle competenze di empatia e comunicazione necessarie nella cura dei pazienti. Lo riferisce South China Morning Post.",
   "more": [
    "La realtà virtuale e mista è sempre più utilizzata in ambito sanitario per preparare psicologicamente i pazienti, specialmente i bambini, a procedure mediche percepite come spaventose. Questi strumenti permettono di simulare ambienti e macchinari ospedalieri, riducendo ansia e stress sia nei piccoli pazienti sia nei familiari."
   ],
