   "titolo": "Le tartarughe liuto in rapido declino: possono salvarle i santuari oceanici?",
   "orig": "Leatherback turtles are declining rapidly. Could a network of ‘ocean sanctuaries’ save them?",
   "lead": "Gli esperti segnalano un rapido declino delle tartarughe liuto e si chiedono se una rete di 'santuari oceanici' possa contribuire a salvarle. Secondo quanto riportato da Euronews, con il ritmo attuale di progresso potrebbero volerci 265 anni per raggiungere l'obiettivo cruciale di proteggere il 30% degli oceani del pianeta. Lo riferisce Euronews.",
   "more": [
    "Le tartarughe liuto sono la specie di tartaruga marina più grande al mondo e sono considerate a rischio a causa della pesca accidentale, dell'inquinamento marino e della perdita degli habitat di nidificazione. L'obiettivo internazionale di proteggere il 30% degli oceani entro il 2030, noto come '30x30', è stato sottoscritto da numerosi paesi nell'ambito di accordi sulla biodiversità."
   ],
