   "titolo": "Identificata nuova specie di dinosauro da un fossile rimasto in un cassetto per un secolo",
   "orig": "New dinosaur species identified from fossil stashed in drawer for a century",
   "lead": "Un gruppo di ricercatori ha identificato una nuova specie di dinosauro a partire da un fossile scoperto sull'Isola di Wight, nel Regno Unito, rimasto conservato in un cassetto per circa un secolo prima di essere riesaminato. Secondo EarthSky, il dinosauro carnivoro sarebbe stato alto quanto un essere umano. Lo riferisce EarthSky.",
   "more": [
    "L'Isola di Wight, nel sud dell'Inghilterra, è uno dei siti paleontologici più importanti d'Europa per i fossili di dinosauri del periodo Cretaceo. Non è raro che reperti conservati in collezioni museali per decenni vengano riesaminati con tecniche moderne, portando all'identificazione di specie non riconosciute al momento del ritrovamento."
   ],
