   "titolo": "A Roma mezza milione di euro di lavoro nero nel settore estetico",
   "orig": "Estetiste, la metà lavora in nero: a Roma business illegale da 300 milioni",
   "lead": "A Roma il settore delle estetiste nasconderebbe un business illegale da circa 300 milioni di euro: secondo Il Messaggero, per ogni estetista che lavora regolarmente ce ne sarebbe un'altra che esercita abusivamente. Il fatturato complessivo del settore nella Capitale, almeno sulla carta, ammonta a circa mezzo miliardo di euro. Lo riferisce Il Messaggero.",
   "more": [
    "Il lavoro nero nel settore dei servizi alla persona, incluse estetiste e centri benessere, è un fenomeno diffuso in diverse città italiane, spesso legato a bassi costi di ingresso nel mercato e difficoltà nei controlli. Le autorità fiscali effettuano periodicamente verifiche per contrastare l'evasione in questi comparti."
   ],
