   "titolo": "Scontri a Milano, l'intelligence in allerta per un nuovo raduno Gen-Z organizzato su TikTok",
   "orig": "Scontri Milano, gli annunci via TikTok: allerta dell'intelligence per il nuovo raduno Gen-Z",
   "lead": "Dopo gli scontri avvenuti durante le manifestazioni di piazza da Torino a Milano, con volanti della polizia danneggiate, cassonetti dati alle fiamme e lancio di pietre e molotov, le autorità italiane sono in allerta per un nuovo raduno annunciato via TikTok dalla cosiddetta Gen-Z. Secondo Il Messaggero, i servizi di intelligence temono che le frange violente che si sono infiltrate nelle proteste possano ripetere gli episodi di violenza. Le fonti non specificano le richieste originarie dei manifestanti né la posizione del governo sul tema. Lo riferisce Il Messaggero.",
   "more": [
    "Negli ultimi anni i social network, in particolare TikTok, sono diventati strumenti centrali per organizzare manifestazioni spontanee tra i giovani, spesso senza una struttura organizzativa tradizionale. Questo rende più difficile per le forze dell'ordine prevedere la partecipazione e individuare in anticipo eventuali infiltrazioni di gruppi violenti nelle proteste pacifiche."
   ],
