   "lead": "Alcuni clienti dei supermercati New World nell'Isola del Nord della Nuova Zelanda potrebbero essere stati sovraccaricati a causa di un problema nei prezzi. Secondo RNZ, almeno due negozi sono stati costretti a chiudere, mentre il personale degli altri punti vendita sta controllando l'accuratezza dei prezzi di tutti i prodotti. Lo riferisce RNZ.",
