   "sez": "cultura",
   "titolo": "Hong Kong punta su panda e panorami per conquistare i delegati dell'Apec",
   "orig": "From pandas to Peak vistas, Hong Kong sets out to captivate Apec delegates",
   "lead": "Hong Kong ha preparato un ricco programma sociale per accogliere circa 500 delegati e ospiti provenienti dalle 21 economie del forum Apec, in occasione della riunione dei ministri delle finanze in corso questa settimana. Secondo la South China Morning Post, che ha ottenuto gli itinerari ufficiali, le attività previste includono panda giganti, giri in autobus scoperto, un corso di cucina cinese, opera tradizionale, una crociera nel porto, il Grande Buddha e una visita a The Peak. Lo riferisce South China Morning Post.",
   "more": [
    "L'Apec (Asia-Pacific Economic Cooperation) è un forum di cooperazione economica che riunisce 21 economie della regione Asia-Pacifico, tra cui Stati Uniti, Cina e Giappone. Gli incontri ministeriali, oltre alle sessioni di lavoro, prevedono spesso programmi culturali e sociali pensati per promuovere l'immagine della città ospitante."
   ],
