   "titolo": "Un'anestesia più verde riduce a metà le emissioni in sala operatoria",
   "orig": "Greener anesthesia cuts operating room emissions in half, slashes anesthetic costs nearly 40%",
   "lead": "Uno studio presentato al congresso Anesthesiology 2026 mostra che gli ospedali possono ridurre sensibilmente l'impatto climatico e i costi della chirurgia modificando le pratiche anestesiologiche di routine, in particolare limitando l'uso di gas anestetici ad alte emissioni, senza compromettere la sicurezza dei pazienti. La ricerca indica che queste misure possono dimezzare le emissioni in sala operatoria e tagliare quasi del 40% i costi degli anestetici. Lo riferisce Medical Xpress.",
   "more": [
    "Alcuni gas anestetici per inalazione, come il desflurano, hanno un potenziale di riscaldamento globale molto elevato rispetto ad alternative come il sevoflurano o l'anestesia endovenosa. Il settore sanitario contribuisce in modo significativo alle emissioni di gas serra; sostituire i gas più inquinanti è considerata una delle strategie più semplici per rendere più sostenibili gli ospedali."
   ],
