   "sez": "tech",
   "titolo": "Le azioni di CXMT scendono dell'8% nonostante utili record",
   "orig": "CXMT shares fall 8% despite blockbuster earnings figures",
   "lead": "Il colosso cinese dei chip di memoria ChangXin Memory Technologies (CXMT) ha visto le proprie azioni perdere oltre l'8% nella seduta di lunedì, nonostante previsioni di utili solidi e un piano di riacquisto di azioni proprie, in un contesto di ribasso generale del settore globale dei semiconduttori. Il titolo è sceso fino a un minimo intraday di 41 yuan, dopo aver chiuso venerdì a 45,02 yuan. Ad agosto le azioni avevano toccato un massimo di 61,8 yuan, in rialzo del 614% rispetto al prezzo dell'IPO di luglio, pari a 8,66 yuan. Lo riferisce South China Morning Post.",
   "more": [
    "CXMT è uno dei principali produttori cinesi di chip di memoria DRAM, settore chiave nella competizione tecnologica tra Cina e Stati Uniti. La volatilità dei titoli dei semiconduttori riflette le incertezze sulla domanda globale e le tensioni commerciali, oltre ai timori di una bolla speculativa dopo le forti ascese di molte azioni tech asiatiche nel 2026."
   ],
