   "id": "zeaf3deab",
   "sez": "ambiente",
   "titolo": "Dalla lince iberica una lezione per i Balcani sulla conservazione",
   "orig": "From 62 animals to a successful recovery: What can the Balkans learn from saving the Iberian lynx?",
   "lead": "Venticinque anni fa la lince iberica era sull'orlo dell'estinzione, con appena 62 esemplari censiti; oggi sulla penisola iberica ne vivono più di 2.600. Secondo Meta.mk, questo risultato non è frutto di una campagna isolata ma di decenni di lavoro congiunto tra istituzioni spagnole e portoghesi, scienziati, comunità locali e Unione Europea. L'articolo propone questo caso come modello possibile per i paesi balcanici, che affrontano sfide simili nella tutela di specie minacciate, sottolineando l'importanza di programmi di conservazione a lungo termine e di collaborazione stabile tra diversi attori.",
   "more": [
    "La lince iberica è il felino più minacciato al mondo tra le grandi specie, ridotta quasi all'estinzione per la perdita di habitat e il calo delle popolazioni di conigli, sua principale fonte di cibo. Programmi di riproduzione in cattività, reintroduzione e protezione degli habitat naturali, sostenuti da fondi europei, hanno permesso la ripresa della popolazione."
   ],
