   "id": "zd60ffbdc",
   "sez": "economia",
   "titolo": "Il mercato del lusso usato cresce in Cina e mette sotto pressione i marchi occidentali",
   "orig": "‘A better deal and spent less’: Western brands under pressure as ‘pre-owned’ luxury booms in China",
   "lead": "Con l'economia cinese ancora in difficoltà nel recupero post-pandemico, anche i grandi marchi del lusso occidentale iniziano a sentire gli effetti della crisi, mentre i consumatori si rivolgono sempre più al mercato dell'usato o a nuovi marchi locali emergenti. I cinesi, che in passato rappresentavano circa un terzo della spesa mondiale nel lusso, stanno cambiando abitudini di acquisto, preferendo articoli di seconda mano che offrono, secondo i consumatori citati, un prezzo migliore con una spesa inferiore. Lo riferisce Hong Kong Free Press.",
   "more": [
    "Il settore del lusso ha tradizionalmente contato molto sulla domanda cinese per sostenere la crescita globale. Il rallentamento economico cinese, legato alla crisi immobiliare e ai consumi più cauti, ha spinto molti consumatori verso il mercato del \"pre-owned\", favorito anche da piattaforme digitali specializzate e da un cambiamento culturale verso un consumo più consapevole."
   ],
