   "id": "z4d4db307",
   "sez": "cultura",
   "titolo": "In Nepal l'altalena tradizionale del Dashain resiste al cambiamento",
   "orig": "As old Dashain customs fade, the village swing holds high",
   "lead": "A Ramechhap, in Nepal, le tradizionali altalene \"linge ping\" continuano a riunire le famiglie durante le celebrazioni del Dashain, nonostante molte usanze del festival stiano gradualmente scomparendo. Secondo il Kathmandu Post, questa tradizione trova oggi nuova diffusione anche grazie ai social media, che permettono ai giovani di condividere momenti legati all'altalena e contribuiscono a mantenerne viva la memoria collettiva, offrendo un'occasione di ritrovo intergenerazionale in un contesto di rapida trasformazione sociale nelle aree rurali del paese. Lo riferisce The Kathmandu Post.",
   "more": [
    "Il Dashain è la festività più importante del Nepal, dedicata alla dea Durga e celebrata con riti familiari e tradizioni che variano da regione a regione. Le altalene di bambù, simbolo di gioia e rinnovamento, sono tipiche delle celebrazioni nelle aree rurali, sebbene l'urbanizzazione e i cambiamenti negli stili di vita ne stiano riducendo la diffusione."
   ],
