   "id": "z74d192b5",
   "sez": "dibattito",
   "titolo": "Minori online, il dibattito sull'educazione digitale oltre i divieti",
   "orig": "Minori online, l'educazione digitale oltre i divieti",
   "lead": "In Italia si discute di come proteggere i minori online, con un dibattito che si concentra sull'opportunità di puntare sull'educazione digitale piuttosto che su semplici divieti d'uso dei social network. L'articolo di Il Messaggero, richiamando una citazione del cantautore Ivano Fossati, invita a cambiare punto di vista per comprendere meglio il fenomeno dell'uso dei social da parte dei più giovani, suggerendo che allontanarsi dalle soluzioni più immediate possa aiutare a individuare approcci più efficaci basati sulla formazione e la consapevolezza digitale.",
   "more": [
    "Il tema della regolamentazione dell'accesso dei minori ai social network è oggetto di discussione in diversi paesi europei, con proposte che vanno dal divieto assoluto sotto una certa età a percorsi di educazione digitale nelle scuole. I sostenitori dell'educazione digitale ritengono che insegnare un uso critico della tecnologia sia più efficace di restrizioni facilmente eludibili dai giovani."
   ],
