   "sez": "ambiente",
   "titolo": "Gli incendi in Indonesia minacciano i progetti di credito di carbonio forestale",
   "orig": "Indonesian wildfires threaten forest carbon projects",
   "lead": "Gli incendi boschivi in Indonesia stanno mettendo a rischio i progetti di conservazione forestale legati ai crediti di carbonio, secondo quanto riportato da Nikkei Asia. Il fenomeno, che colpisce ampie aree del paese, rischia di compromettere gli investimenti internazionali destinati alla protezione delle foreste e alla riduzione delle emissioni, elementi centrali per la credibilità dei mercati del carbonio basati su progetti di conservazione forestale in Indonesia. Lo riferisce Nikkei Asia.",
   "more": [
    "I crediti di carbonio forestale sono strumenti finanziari che permettono a imprese e governi di compensare le proprie emissioni finanziando la protezione di foreste che altrimenti rischierebbero la deforestazione. Se le aree protette vengono distrutte dagli incendi, il valore ambientale ed economico di questi progetti viene meno, minando la fiducia degli investitori."
   ],
