   "titolo": "La Rochelle onora la memoria di Hyron Andrews nella Champions Cup",
   "orig": "TRAGIC TRIBUTES: La Rochelle players and fans honour Hyron Andrews’ memory with compassion and class",
   "lead": "I giocatori e i tifosi del La Rochelle hanno reso omaggio alla memoria di Hyron Andrews durante una giornata di partite della Champions Cup segnata dal lutto, secondo Daily Maverick. I tifosi francesi e il club hanno mostrato compostezza e rispetto in un giorno di gare giocato all'ombra della tragedia, offrendo un tributo che la testata descrive come esempio di dignità sportiva in un momento emotivamente difficile per le squadre coinvolte. Lo riferisce Daily Maverick.",
