   "id": "ze0ef2129",
   "sez": "cultura",
   "titolo": "Una nuova generazione di srilankesi trasforma la scena gastronomica di Colombo",
   "orig": "How a new generation of Sri Lankans is reshaping Colombo’s restaurant and bar scene",
   "lead": "Per decenni Colombo è stata considerata più una tappa di passaggio tra l'aeroporto e le coste turistiche dello Sri Lanka che una destinazione culturale, ma la situazione sta cambiando. Secondo South China Morning Post, mentre il paese continua a recuperare dalla guerra civile durata ventisei anni (1983-2009) e dalla crisi economica del periodo 2019-2024, la capitale sta vivendo una nuova vitalità nella scena della ristorazione e dell'ospitalità, grazie a una nuova generazione di srilankesi che sta ridefinendo bar e ristoranti locali. Lo riferisce South China Morning Post.",
   "more": [
    "Lo Sri Lanka ha affrontato negli ultimi anni una grave crisi economica, con carenza di valuta estera e proteste che portarono alla caduta del governo nel 2022. La ripresa del turismo e dell'imprenditoria locale, soprattutto nel settore della ristorazione, è vista come un segnale di normalizzazione economica e sociale del paese."
   ],
