   "titolo": "\"Belles de nuit\" di Khadija Lemkecher vince il Grand Prix del festival CINALMA",
   "orig": "« Belles de nuit » de Khadija Lemkecher reçoit le Grand Prix du festival CINALMA",
   "lead": "Il film \"Belles de nuit\" (Nawar Achiaa), primo lungometraggio della regista Khadija Lemkecher, ha vinto il prestigioso Grand Prix del festival CINALMA in Francia, imponendosi tra diciassette film provenienti da tutto il bacino mediterraneo. Secondo La Presse de Tunisie, si tratta di una vittoria significativa che va oltre il premio stesso, in una selezione descritta come particolarmente esigente. Lo riferisce La Presse de Tunisie.",
