   "id": "zaaae6722",
   "sez": "sport",
   "titolo": "Il Ruanda conquista la Formula 1 e ridisegna le prospettive infrastrutturali africane per il 2030",
   "orig": "Rwanda bags Formula One, blows up Africa’s 2030 infrastructure report card",
   "lead": "Il Ruanda ha ottenuto l'organizzazione di una gara di Formula 1, un risultato che secondo The EastAfrican rimette in discussione le previsioni sullo sviluppo infrastrutturale del continente africano per il 2030. Il Gran Premio africano rappresenterà, nei prossimi quattro o cinque anni, solo una parte limitata di un più ampio programma di investimenti, ma la testata ne sottolinea il valore simbolico come segnale della crescente capacità del Ruanda di attrarre grandi eventi sportivi internazionali. Lo riferisce The EastAfrican.",
   "more": [
    "La Formula 1 ha negli ultimi anni ampliato il proprio calendario verso nuovi mercati, inclusi paesi emergenti, come parte di una strategia di espansione globale. Per i paesi ospitanti, organizzare un Gran Premio comporta investimenti infrastrutturali significativi, in cambio di visibilità internazionale e potenziali ricadute economiche sul turismo e sull'immagine del paese."
   ],
