   "sez": "tech",
   "titolo": "Anthropic destinerà il 5% delle sue azioni a un fondo di beneficenza pubblica",
   "orig": "Anthropic says it will commit 5% of its shares to 'public benefit fund'",
   "lead": "L'azienda di intelligenza artificiale Anthropic, creatrice del chatbot Claude, ha annunciato che destinerà il 5% delle proprie azioni a un «fondo per il beneficio pubblico». L'annuncio arriva mentre la società si prepara a una quotazione in borsa di grande rilievo. Secondo l'azienda, il fondo potrà essere utilizzato per donazioni a organizzazioni non governative e per «distribuzioni dirette a popolazioni specifiche». Lo riferisce la BBC.",
   "more": [
    "Anthropic è una delle principali aziende di intelligenza artificiale generativa, fondata da ex dipendenti di OpenAI e sostenuta da investitori come Amazon e Google. Una quotazione in borsa consentirebbe all'azienda di raccogliere ulteriori capitali vendendo azioni sul mercato pubblico."
   ],
