   "sez": "mondo",
   "titolo": "Papa Leone XIV torna in piazza San Pietro dopo l'intervento al polmone",
   "orig": "Pope greeted by crowds in first major appearance since lung cancer surgery",
   "lead": "Papa Leone XIV è apparso domenica davanti a migliaia di fedeli in piazza San Pietro, al Vaticano, nella prima uscita pubblica importante dopo l'intervento chirurgico per un cancro al polmone. Il pontefice ha ringraziato i fedeli per le preghiere ricevute durante la degenza in ospedale e ha annunciato un ritorno graduale alle sue consuete attività. La folla ha accolto con calore l'apparizione del Papa, segnando un momento significativo nel suo percorso di recupero.",
   "more": [
    "Piazza San Pietro è il luogo simbolo delle udienze e degli annunci pubblici del pontefice. Un intervento chirurgico per cancro al polmone comporta tipicamente un periodo di convalescenza durante il quale le attività pubbliche vengono sospese o ridotte."
   ],
