 "contesti": {
  "z9e6b8a28": "La campagna per il ballottaggio si è intensificata nelle ultime settimane con sondaggi che indicano una gara serrata tra i due candidati. Il dibattito di domenica rappresentava il primo confronto diretto tra Lula e Flávio Bolsonaro prima del voto decisivo fissato per il 25 ottobre.",
  "z376cf408": "Nei giorni scorsi la legislazione sanzionatoria contro la Russia era prossima a entrare in vigore, mentre proseguivano gli attacchi russi contro infrastrutture ucraine. Trump aveva già manifestato aperture verso Mosca, alimentando dubbi sugli alleati europei riguardo alla fermezza americana nel sostegno a Kiev.",
  "z6c02f0a8": "Nei trimestri precedenti la crescita cinese aveva mostrato un progressivo rallentamento, scendendo al 4,3% tra aprile e giugno, il livello più basso da oltre tre anni, a causa della debolezza dei consumi interni e delle tensioni sul commercio globale con gli Stati Uniti.",
  "z1852a75f": "Nei giorni precedenti Milano aveva già vissuto episodi di tensione e disordini, con danni a negozi e strutture pubbliche. Le autorità avevano intensificato i controlli, ma la situazione non si è placata, portando a nuovi scontri nel centro città e a un acceso scambio di accuse tra amministrazione comunale e governo.",
  "z3a999971": "Negli ultimi mesi Anthropic ha rafforzato la propria posizione nel settore dell'intelligenza artificiale, attirando investimenti crescenti e preparando il terreno per un possibile ingresso in borsa, in un contesto di forte competizione con altre aziende del settore come OpenAI.",
  "z4a661600": "Nei giorni precedenti il Papa era stato ricoverato in ospedale per sottoporsi a un intervento chirurgico al polmone legato a una diagnosi di cancro, sospendendo temporaneamente le proprie attività pubbliche e le udienze consuete in Vaticano.",
  "zd8350245": "Il Brighton ha iniziato la stagione di Premier League con risultati positivi sotto la guida di Fabian Hürzeler, confermandosi tra le squadre in forma del campionato nelle ultime settimane.",
  "z0ae6debf": "Nelle ultime giornate di Liga il Real Madrid ha inseguito il Barcellona in classifica, cercando continuità di risultati in vista dell'attesissimo Clasico.",
  "zc0641b77": "Nelle ultime settimane il Manchester United ha attraversato una crisi di risultati, con la sconfitta in Champions League contro l'Atletico Madrid che ha acceso le critiche interne alla gestione del club.",
  "zacc7b607": "Dal 2022, dopo l'accordo della Cop15 di Montreal, i governi lavorano all'attuazione degli obiettivi di protezione della biodiversità, ma i rapporti recenti segnalano ritardi nei finanziamenti e nell'attuazione delle misure nazionali.",
  "z321d78c2": "Le manifestazioni sono iniziate alcuni giorni prima, inizialmente pacifiche, per poi intensificarsi fino a trasformarsi in scontri diretti con le forze dell'ordine e in incendi di edifici pubblici a Tirana.",
  "z57108922": "Negli ultimi mesi nel Pd si è discusso del percorso verso la scelta del candidato premier per le prossime elezioni, con tensioni tra la segreteria guidata da Schlein e la componente riformista del partito sul ricorso alle primarie.",
  "zc20b25d3": "La questione degli aumenti agli stipendi dei magistrati era già emersa nelle settimane precedenti durante la discussione della manovra, con il governo che ha più volte segnalato difficoltà a reperire le risorse necessarie per onorare gli adeguamenti previsti dalle norme vigenti.",
  "zec82ce43": "Nei giorni precedenti al 17 ottobre si erano già registrate mobilitazioni liceali e sociali in Francia legate al caro vita e a rivendicazioni sul potere d'acquisto, in un clima di crescente tensione politica attorno al governo di Macron.",
  "z3779b443": "Nelle settimane scorse la Francia è stata attraversata da una nuova ondata di tensioni sociali legate a politiche economiche e di bilancio contestate dai manifestanti. A Limoges, come in altre città francesi, i cortei di protesta si sono intensificati, culminando in disordini che hanno coinvolto edifici pubblici. Il municipio cittadino, simbolo storico della comunità locale, è stato incendiato durante gli scontri, lasciando i residenti attoniti davanti ai danni subiti dalla struttura."
 },
