   "divergono": "Le testate attribuiscono cause diverse alla crisi: Deutsche Welle riporta la tesi di Rama di un'ingerenza esterna e la cornice europea, mentre BBC News e The Guardian concentrano il racconto su corruzione interna e scandali specifici (Hyseni/Agasi per BBC, costi universitari per Guardian). Le cifre su feriti e arresti differiscono: BBC parla di 80 denunce e centinaia di arresti/indagini, Guardian di 35 detenuti e 23 agenti più 6 civili feriti. Al Jazeera, pur non leggibile, segnala un fatto specifico - l'incendio alla Corte Suprema - assente negli altri testi. BBC parla di rubber bullets usati per la prima volta, dettaglio non presente altrove."
